input:
{
  "title": "Facebook Profile Scraper Input",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "startUrls": {
      "title": "Profile URLs or usernames",
      "type": "array",
      "editor": "stringList",
      "description": "Public Facebook profiles to scrape. Accepts full URLs (https://www.facebook.com/zuck), mobile URLs, numeric profile URLs (https://www.facebook.com/profile.php?id=4), or bare usernames (zuck). Duplicates are removed. One dataset record is produced per profile.",
      "prefill": [
        "https://www.facebook.com/zuck"
      ]
    },
    "maxItems": {
      "title": "Max profiles",
      "type": "integer",
      "description": "Maximum number of profiles to scrape in this run. Set 0 to process every profile in the list.",
      "default": 100,
      "minimum": 0
    },
    "proxyConfiguration": {
      "title": "Proxy configuration",
      "type": "object",
      "editor": "proxy",
      "description": "Proxy used to load the public profile page that contains the Intro details (work, education, hometown, current city, relationship). Residential proxies are strongly recommended - datacenter IPs are frequently blocked.",
      "default": {
        "useApifyProxy": true,
        "apifyProxyGroups": [
          "RESIDENTIAL"
        ]
      },
      "prefill": {
        "useApifyProxy": true,
        "apifyProxyGroups": [
          "RESIDENTIAL"
        ]
      }
    }
  },
  "required": [
    "startUrls"
  ]
}
